from pathlib import Path
import json, html, re, zipfile

ROOT=Path(__file__).resolve().parents[1]
products=json.loads((ROOT/'assets/products.json').read_text(encoding='utf-8'))
for i,p in enumerate(products):
    p['art']=i
    for k in ['image','gallery','rating','reviewsCount','badge','badgeText']: p.pop(k,None)
(ROOT/'assets/js/catalog.js').write_text('window.NAIL_PRODUCTS = '+json.dumps(products,ensure_ascii=False)+';',encoding='utf-8')

def icon(name):
    paths={'search':'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>','heart':'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>','bag':'<path d="M5 7h14l1 14H4L5 7Z"/><path d="M9 8V6a3 3 0 0 1 6 0v2"/>','menu':'<path d="M3 6h18M3 12h18M3 18h18"/>'}
    return '<svg viewBox="0 0 24 24" width="21" height="21" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true">'+paths[name]+'</svg>'

def art(i,cls=''):
    return f'<div class="nail-art art-{i} {cls}" role="img" aria-label="Illustrated {html.escape(products[i]["name"])} nail design"></div>'

def card(p):
    return f'''<article class="product-card"><div class="product-picture"><a href="product.html?id={p['id']}" aria-label="View {p['name']}">{art(p['art'])}</a><button class="save-button" data-save="{p['id']}" aria-label="Save {p['name']}" aria-pressed="false">{icon('heart')}</button></div><div class="product-meta"><span>{p['categoryLabel']}</span><span>Handcrafted</span></div><a class="product-name" href="product.html?id={p['id']}">{p['name']}</a><div class="product-bottom"><span>₹{p['price']:,}</span><a href="product.html?id={p['id']}" aria-label="Choose options for {p['name']}">Choose your set ↗</a></div></article>'''

def heading(kicker,title,desc=''):
    return f'<header class="page-heading"><p class="eyebrow">{kicker}</p><h1>{title}</h1><p class="intro">{desc}</p></header>'

def faq(q,a): return f'<details><summary>{q}<span aria-hidden="true">+</span></summary><div class="answer">{a}</div></details>'

nav=[('shop.html','The collection'),('about.html','Our story'),('size-guide.html','Find your fit'),('nail-care.html','Nail care')]
