# Preserve existing policy text and terms; remove placeholder contacts and unsupported automatic notifications.
with zipfile.ZipFile(ROOT/'docs/before-redesign.zip') as backup:
 for filename,title in [('shipping-policy.html','Shipping policy'),('returns-exchanges.html','Returns & exchanges'),('privacy-policy.html','Privacy policy'),('terms-conditions.html','Terms & conditions')]:
    raw=backup.read(filename).decode('utf-8-sig')
    start=raw.find('<div class="policy-body">')
    match=re.search(r'</main>',raw[start:])
    body=raw[start:start+match.start()] if start>=0 and match else ''
    # Extract content up to the end of the policy div by counting nested divs.
    depth=0; end=0
    for token in re.finditer(r'<div\b[^>]*>|</div>',body):
        depth+= -1 if token.group()=='</div>' else 1
        if depth==0: end=token.end();break
    body=body[:end]
    body=re.sub(r' style="[^"]*"','',body)
    body=re.sub(r'<a[^>]*href="(?:https://wa.me/[^\"]*|mailto:[^\"]*)"[^>]*>.*?</a>','<a href="contact.html">Contact information</a>',body,flags=re.S)
    body=re.sub(r'\+91\s*98765\s*43210|hello@nailaurabyabha.com','the contact channel listed on our contact page',body)
    body=body.replace('you will receive an automatic dispatch notification','the studio will need to provide a dispatch notification')
    page(filename,title,heading('THE FINER DETAILS',title,'A little clarity for a thoughtful shopping experience.')+'<section class="wrap narrow policy-section"><p class="notice">Online ordering is currently unavailable. These existing store policies are provided for reference and must be confirmed before orders open.</p>'+body+'</section>')

page('404.html','Page not found','<section class="closing wrap error-page"><p class="eyebrow">404 / A LITTLE DETOUR</p><h1>This page has<br><em>slipped away.</em></h1><p>Let’s find you something beautiful instead.</p><a class="button" href="shop.html">Back to the collection ↗</a><a class="text-link" href="index.html">Take me home →</a></section>')
print('Built 16 pages with shared branding and navigation.')


